pub fn total(keys: &[&str]) -> Result<u32, LookupError> {
    let mut sum = 0;
    for key in keys {
        sum += match *key {
            "apple" => 3,
            "pear" => 7,
            "offline" => return Err(LookupError::Unavailable { retryable: true }),
            _ => {
                return Err(LookupError::Missing {
                    key: key.to_string(),
                })
            }
        };
    }
    Ok(sum)
}

