func Handler(items []Item) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		q := r.URL.Query()
		o, l, bad := 0, -1, false
		for n, p := range map[string]*int{"offset": &o, "limit": &l} {
			if v, ok := q[n]; ok && !bad {
				x, err := strconv.Atoi(v[0])
				bad = err != nil || x < 0
				if !bad {
					*p = x
				}
			}
		}
		if bad {
			http.Error(w, "invalid pagination", http.StatusBadRequest)
			return
		}
		k := q.Get("kind")
		res := make([]Item, 0)
		for i, skip := 0, o; i < len(items) && (l < 0 || len(res) < l); i++ {
			if k != "" && items[i].Kind != k {
				continue
			}
			if skip > 0 {
				skip--
				continue
			}
			res = append(res, items[i])
		}
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(res)
	})
}

