func TestRecordContractAndFollowUps(t *testing.T) {
	records := Produce([]string{"alpha", "beta"})
	if want := []Record{{ID: 1, Text: "alpha"}, {ID: 2, Text: "beta"}}; !reflect.DeepEqual(records, want) {
		t.Fatalf("Produce: %v, want %v", records, want)
	}
	if got := Consume(records); !reflect.DeepEqual(got, []string{"1:alpha", "2:beta"}) {
		t.Fatalf("Consume: %q", got)
	}
	if kept, dropped := Stats([]string{"alpha", "beta"}); kept != 2 || dropped != 0 {
		t.Fatalf("Stats: kept %d, dropped %d", kept, dropped)
	}
	if got := Duplicates([]string{"a", "b", "a"}); !reflect.DeepEqual(got, []string{"a"}) {
		t.Fatalf("Duplicates: %q", got)
	}
