func TestInvoice(t *testing.T) {
	sample := core.Invoice{ID: "INV-7", Customer: "Acme Ltd", Currency: "USD", Lines: []core.LineItem{
		{SKU: "BK-1", Qty: 3, Unit: 1250, Category: "books"},
		{SKU: "MUG", Qty: 7, Unit: 333, Category: "home"},
		{SKU: "TEA", Qty: 1, Unit: 499, Category: "food"},
	}}
	rules, err := discount.ParseRules("percent books 10%\nbundle MUG 2 1\n")
	if err != nil {
		t.Fatal(err)
	}
	taxes, err := tax.ParseTable("default 20%\nrate food 5%\nrate books 0%\n")
	if err != nil {
		t.Fatal(err)
	}

	t.Run("money", func(t *testing.T) {
		for s, want := range map[string]core.Money{"12.50": 1250, "-3": -300, "0.5": 50, "007.05": 705, "-0": 0,
			"92233720368547758.07": 1<<63 - 1, "-92233720368547758.08": -1 << 63} {
			if got, err := core.ParseMoney(s); err != nil || got != want {
				t.Errorf("ParseMoney(%q) = %d, %v; want %d", s, got, err, want)
			}
		}
		for _, s := range []string{"", "-", "1.", ".5", "1.234", "+1", " 1", "1e3", "92233720368547758.08"} {
			if _, err := core.ParseMoney(s); err == nil {
				t.Errorf("ParseMoney(%q) succeeded", s)
			}
		}
		for m, want := range map[core.Money]string{1250: "12.50", -5: "-0.05", 0: "0.00", -1 << 63: "-92233720368547758.08"} {
			if got := m.String(); got != want {
				t.Errorf("Money(%d).String() = %q; want %q", int64(m), got, want)
			}
		}
		for s, want := range map[string]core.Rate{"0.9137": 913700, "8.25%": 82500, "100%": 1000000, "0.000001": 1, "007.5%": 75000} {
			if got, err := core.ParseRate(s); err != nil || got != want {
				t.Errorf("ParseRate(%q) = %d, %v; want %d", s, got, err, want)
			}
		}
		for _, s := range []string{"", "-1", "+1", "1.2345678", "12.34567%", "%", "1 %", "99999999999999999999"} {
			if _, err := core.ParseRate(s); err == nil {
				t.Errorf("ParseRate(%q) succeeded", s)
			}
		}
		for r, want := range map[core.Rate]string{82500: "8.25%", 1000000: "100%", 0: "0%", 1: "0.0001%"} {
			if got := r.String(); got != want {
				t.Errorf("Rate(%d).String() = %q; want %q", int64(r), got, want)
			}
		}
		if got := core.Money(1999).MulRate(500000); got != 1000 {
			t.Errorf("MulRate half: %d", got)
		}
		if got := core.Money(-1999).MulRate(500000); got != -1000 {
			t.Errorf("MulRate negative half: %d", got)
		}
		if got := core.DivRound(-7, 2); got != -4 {
			t.Errorf("DivRound(-7, 2) = %d", got)
		}
		defer func() {
			if recover() == nil {
				t.Error("DivRound by zero did not panic")
			}
		}()
		core.DivRound(1, 0)
	})

	t.Run("model", func(t *testing.T) {
		if got := sample.Subtotal(); got != 3750+2331+499 {
			t.Errorf("Subtotal = %d", got)
		}
		if err := sample.Validate(); err != nil {
			t.Fatalf("Validate: %v", err)
		}
		for name, c := range map[string]struct {
			edit func(*core.Invoice)
			line int
		}{
			"spaced ID":      {func(i *core.Invoice) { i.ID = "INV 7" }, 0},
			"blank customer": {func(i *core.Invoice) { i.Customer = " \t" }, 0},
			"lower currency": {func(i *core.Invoice) { i.Currency = "usd" }, 0},
			"no lines":       {func(i *core.Invoice) { i.Lines = nil }, 0},
			"repeated SKU":   {func(i *core.Invoice) { i.Lines[2].SKU = "BK-1" }, 3},
			"zero quantity":  {func(i *core.Invoice) { i.Lines[1].Qty = 0 }, 2},
			"negative unit":  {func(i *core.Invoice) { i.Lines[0].Unit = -1 }, 1},
			"bad category":   {func(i *core.Invoice) { i.Lines[1].Category = "Home" }, 2},
			"first rule":     {func(i *core.Invoice) { i.Lines[0].Qty = 0; i.Lines[0].Category = "" }, 1},
		} {
			inv := sample
			inv.Lines = append([]core.LineItem(nil), sample.Lines...)
