			{"off PEN 0.50", item("PEN", 4, 30, "office"), 120},
			{"percent home 10%\nbundle MUG 2 1", item("MUG", 3, 300, "home"), 300},
			{"", item("MUG", 3, 300, "home"), 0},
		} {
