			}
		}
		for _, text := range []string{"percent books 101%", "percent books 10% min 0", "tier books 5:5% 3:10%", "bundle X 2 0", "off X 0", "vat books 10%"} {
			parsed, err := discount.ParseRules("# rules\n\npercent food 5%\n" + text)
