func Statement(inv core.Invoice, rules []discount.Rule, taxes tax.Table, rates fx.Table, currency string) (Summary, string, error) {
	if err := inv.Validate(); err != nil {
		return Summary{}, "", err
	}
	s := Summarize(inv)
	cols := []render.Column{{Title: "SKU"}, {Title: "Qty", Right: true}, {Title: "Unit", Right: true},
		{Title: "Discount", Right: true}, {Title: "Tax", Right: true}, {Title: "Amount", Right: true}}
	var rows [][]string
	for _, l := range inv.Lines {
		off := discount.Line(l, rules)
		tx := taxes.Line(l, l.Gross()-off)
		s.Discount += off
		s.Tax += tx
		rows = append(rows, []string{l.SKU, strconv.FormatInt(l.Qty, 10), l.Unit.String(),
			off.String(), tx.String(), (l.Gross() - off + tx).String()})
	}
	s.Total = s.Subtotal - s.Discount + s.Tax
	converted, err := rates.Convert(s.Total, inv.Currency, currency)
	if err != nil {
		return Summary{}, "", err
	}
	s.Currency, s.Converted = currency, converted
	footer := [][]string{total("Subtotal", s.Subtotal), total("Discount", s.Discount),
		total("Tax", s.Tax), total("Total", s.Total)}
	if currency != inv.Currency {
		footer = append(footer, total("Total in "+currency, converted))
	}
	head := fmt.Sprintf("Invoice %s for %s (%s)\n", inv.ID, inv.Customer, inv.Currency)
	return s, head + render.Table(cols, rows, footer), nil
}

