// Markdown lays out the same table as a Markdown pipe table.
func Markdown(cols []Column, rows, footer [][]string) string {
	if len(cols) == 0 {
		return ""
	}
	var b strings.Builder
	write := func(cells []string) {
		b.WriteString("|")
		for i := range cols {
			cell := ""
			if i < len(cells) {
				cell = strings.ReplaceAll(cells[i], "\n", "<br>")
			}
			b.WriteString(" " + cell + " |")
		}
		b.WriteString("\n")
	}
	titles, align := make([]string, len(cols)), make([]string, len(cols))
	for i, c := range cols {
		titles[i], align[i] = c.Title, "---"
		if c.Right {
			align[i] = "--:"
		}
	}
	write(titles)
	write(align)
	for _, row := range rows {
		write(row)
	}
	for _, row := range footer {
		write(row)
	}
	return b.String()
}

