func (inv Invoice) Validate() error {
	switch {
	case !isToken(inv.ID):
		return &Error{Msg: fmt.Sprintf("invalid ID %q", inv.ID)}
	case strings.TrimSpace(inv.Customer) == "":
		return &Error{Msg: "missing customer"}
	case len(inv.Currency) != 3 || strings.Trim(inv.Currency, "ABCDEFGHIJKLMNOPQRSTUVWXYZ") != "":
		return &Error{Msg: fmt.Sprintf("invalid currency %q", inv.Currency)}
	case len(inv.Lines) == 0:
		return &Error{Msg: "no lines"}
	}
	seen := map[string]bool{}
	for i, l := range inv.Lines {
		fail := func(format string, args ...any) error {
			return &Error{Line: i + 1, Msg: fmt.Sprintf(format, args...)}
		}
		switch {
		case !isToken(l.SKU):
			return fail("invalid SKU %q", l.SKU)
		case seen[l.SKU]:
			return fail("repeated SKU %q", l.SKU)
		case l.Qty < 1:
			return fail("quantity %d is not positive", l.Qty)
		case l.Unit < 0:
			return fail("negative unit price %s", l.Unit)
		case l.Category == "" || strings.Trim(l.Category, "abcdefghijklmnopqrstuvwxyz0123456789-") != "":
			return fail("invalid category %q", l.Category)
		}
		seen[l.SKU] = true
	}
	return nil
}

