func (inv Invoice) Validate() error {
	var bad *Error
	ok := true
	for i := -1; i < len(inv.Lines) && ok; i++ {
		if i < 0 {
			msg := ""
			if !isToken(inv.ID) {
				msg = fmt.Sprintf("invalid ID %q", inv.ID)
			} else {
				if strings.TrimSpace(inv.Customer) == "" {
					msg = "missing customer"
				} else if len(inv.Currency) != 3 || strings.Trim(inv.Currency, "ABCDEFGHIJKLMNOPQRSTUVWXYZ") != "" {
					msg = fmt.Sprintf("invalid currency %q", inv.Currency)
				} else if len(inv.Lines) == 0 {
					msg = "no lines"
				}
			}
			if msg != "" {
				bad, ok = &Error{Msg: msg}, false
			}
			continue
		}
		l := inv.Lines[i]
		dup := false
		for j := 0; j < i; j++ {
			if inv.Lines[j].SKU == l.SKU {
				dup = true
			}
		}
		n := 0
		for _, broken := range []bool{!isToken(l.SKU), dup, l.Qty < 1, l.Unit < 0,
			l.Category == "" || strings.Trim(l.Category, "abcdefghijklmnopqrstuvwxyz0123456789-") != ""} {
			if broken {
				break
			}
			n++
		}
		if n < 5 {
			reasons := []string{"invalid SKU", "repeated SKU", "quantity is not positive", "negative unit price", "invalid category"}
			bad, ok = &Error{Line: i + 1, Msg: reasons[n]}, false
		}
	}
	if ok {
		return nil
	}
	return bad
}

